{
  "items": [
    {
      "title": "Bildung in Duisburg – Kommunaler Bildungsbericht (Historical Data 2000–2009)",
      "url_or_doi": "https://www.duisburg.de/microsites/bildungsregion_duisburg/aktuelles/duisburger-bildungsberichterstattung.php.media/73836/Bildung_in_Duisburg_-_1._Teilbericht.pdf",
      "justification": "Highly relevant historical source published by the City of Duisburg. Includes statistical data from municipal surveys conducted between 2000 and 2009, covering vocational qualifications, apprenticeship contracts, vocational school education, and educational attainment. Data are broken down by Duisburg districts and demographic characteristics. Particularly useful for examining vocational education participation and qualifications during the 2000s. The statistics are embedded in a PDF report rather than supplied as a standalone downloadable dataset."
    },
    {
      "title": "Regionalverband Ruhr – Statistikportal Ruhr: Vocational Education and Training Statistics",
      "url_or_doi": "https://statistikportal.ruhr/",
      "justification": "Regional statistical database covering Duisburg and other municipalities in the Ruhr metropolitan area. Provides education-related indicators at the district and independent-city levels, including vocational education, school qualifications, and transitions through the education system. Useful for comparing Duisburg with neighboring municipalities. Historical coverage varies by indicator, so availability for individual years between 2000 and 2009 should be verified."
    },
    {
      "title": "Bildungsbericht Ruhr – Vocational Education and Continuing Training",
      "url_or_doi": "https://www.duisburg.de/microsites/bildungsregion_duisburg/aktuelles/duisburger-bildungsberichterstattung.php.media/73838/Bildungsbericht_Ruhr.pdf",
      "justification": "Regional education report containing statistical tables on vocational education, apprenticeships, vocational schools, and continuing education in the Ruhr region, including Duisburg. Particularly relevant because it includes historical comparisons between 2000 and 2009. Its vocational education and adult learning sections provide information on training participation and educational developments. Suitable for historical analysis, although some indicators are reported at the regional rather than municipal level."
    },
    {
      "title": "GovData – Vocational Training Statistics: Apprentices by Place of Residence, Training Sector, and Training Location",
      "url_or_doi": "https://www.govdata.de/suche/daten/berufsbildungsstatistik-auszubildende-nach-wohnort-beivertragsabschluss-ausbildungsbereichen-6-",
      "justification": "Official German open-data catalogue entry for vocational training statistics at the district and independent-city level. Covers apprentices according to their residence when signing a training contract, training sector, and location of the training establishment. Duisburg can be selected as a geographical unit. Particularly useful for studying the geographical distribution of apprenticeships and differences between residents and training locations. Historical availability for 2000–2009 requires verification."
    },
    {
      "title": "Statistikportal Deutschland – Regional Statistical Databases",
      "url_or_doi": "https://www.statistikportal.de/de/datenbanken",
      "justification": "Official gateway to German federal and state statistical databases, including regional education and vocational training statistics. Provides access to data for independent cities such as Duisburg. Relevant indicators include apprentices, vocational education institutions, and education participation. Useful for constructing historical time series and comparing Duisburg with other German cities. The gateway itself is not a dataset, and coverage of the 2000s depends on the selected database and statistical series."
    },
    {
      "title": "IT.NRW – Vocational Training Statistics in North Rhine-Westphalia, 2011",
      "url_or_doi": "https://webshop.it.nrw.de/download.php?id=17921",
      "justification": "Official statistical publication from Information und Technik Nordrhein-Westfalen (IT.NRW). Contains historical vocational training statistics, including annual apprenticeship figures for 2000–2009. Data are differentiated by training sector, such as industry and commerce, skilled trades, agriculture, public administration, and liberal professions. Particularly useful for reconstructing vocational training trends during the 2000s. The identified historical series are primarily statewide; Duisburg-specific breakdowns must be checked within the publication."
    },
    {
      "title": "IT.NRW – Vocational Training Statistics in North Rhine-Westphalia, 2013",
      "url_or_doi": "https://webshop.it.nrw.de/download.php?id=19298",
      "justification": "Official statistical report containing historical apprenticeship and vocational training figures for North Rhine-Westphalia, including observations from the 2000s. Provides information on apprenticeship participation and training sectors. Useful for comparing historical vocational education developments and examining structural changes in training provision. Its relevance to Duisburg depends on the geographical breakdowns available in the detailed tables."
    },
    {
      "title": "BIBB – Newly Concluded Apprenticeship Contracts, Unplaced Applicants, Unfilled Training Positions, Supply and Demand (2009)",
      "url_or_doi": "https://www.bibb.de/de/6994.php",
      "justification": "Official dataset from the German Federal Institute for Vocational Education and Training (BIBB). Contains information on newly concluded apprenticeship contracts, applicants without placements, unfilled apprenticeship positions, and vocational training supply and demand. The underlying series includes data from 2004 onward, making it relevant to the latter half of the 2000s. Useful for analyzing apprenticeship market conditions, although Duisburg-level availability must be checked."
    },
    {
      "title": "BIBB – Datensystem Auszubildende (DAZUBI)",
      "url_or_doi": "https://www.bibb.de/de/12129.php",
      "justification": "Official vocational training statistics database maintained by BIBB. Provides detailed apprenticeship statistics by occupation and other characteristics, with supplementary statistical tables available from reporting year 2009. Relevant for studying the final year of the requested period and establishing a baseline for subsequent developments. Geographic detail varies, and not all tables provide municipal-level observations for Duisburg."
    },
    {
      "title": "Bildung in Deutschland 2008 – Historical Education Data",
      "url_or_doi": "https://www.bildungsbericht.de/de/datengrundlagen/daten-2008",
      "justification": "Official underlying datasets for Germany's 2008 national education report. Includes downloadable Excel tables on vocational education, the structure of vocational training entry, and transitions from general schooling into vocational training. Particularly valuable for examining educational conditions during the 2000s. Data are primarily national or state-level, so this source is best used to contextualize Duisburg rather than as a direct municipal dataset."
    },
    {
      "title": "Wegweiser Kommune – Duisburg Education Report and Municipal Indicators",
      "url_or_doi": "https://www.wegweiser-kommune.de/berichte/bildungsbericht%2Bduisburg",
      "justification": "Municipal education indicator resource covering Duisburg. Includes education and training-related indicators, such as youth participation in continuing education and labor-market integration measures. The resource identifies its data as available under a CC0 license. Useful for contextualizing local vocational education and employment transitions, although the availability of observations specifically from 2000–2009 needs to be confirmed."
    }
  ]
}
